  public sealed class UpdateListView : Control {
    public static UpdateItem[] SectionRows(UpdateItem[] rows){var names=new[]{"Программа","Движки","Дополнительный софт","Стратегии","Текущие выходы — их списки"};var result=new System.Collections.Generic.List<UpdateItem>();for(int n=0;n<names.Length;n++){var group=rows.Where(r=>Section(r)==n&&(r.Kind!="catalog"||!rows.Any(x=>x.Kind=="optional"))).ToArray();if(group.Length==0)continue;result.Add(new UpdateItem{Id="section:"+n,Kind="section",Name=names[n]});result.AddRange(group);}return result.ToArray();}
    static int Section(UpdateItem row){return row.Id=="app"?0:row.Kind=="list"?4:row.Id.EndsWith("-config")?3:row.Id=="telegram"||row.Id=="warp"||row.Id=="zapret"?2:1;}
    const int HeaderHeight=42,RowHeight=62;
    public UpdateItem[] Items=new UpdateItem[0];public int SelectedIndex=-1;int first,dragOffset=-1;public event Action SelectionChanged;readonly ToolTip tips=new ToolTip();readonly Font groupFont=new Font("Segoe UI",14,GraphicsUnit.Pixel);
    public UpdateListView(){Name="updateList";SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);BackColor=Color.FromArgb(28,44,79);Font=new Font("Segoe UI",16,GraphicsUnit.Pixel);TabStop=true;Disposed+=(s,e)=>{tips.Dispose();groupFont.Dispose();Font.Dispose();};}
    public UpdateItem Selected{get{return SelectedIndex>=0&&SelectedIndex<Items.Length&&Items[SelectedIndex].Kind!="section"?Items[SelectedIndex]:null;}}
    public int VisibleRows{get{return Math.Max(1,(Height-HeaderHeight)/RowHeight);}}
    public int FirstVisibleRow{get{return first;}}
    public Rectangle[] Columns{get{int width=Math.Max(1,Width-16),name=(int)(width*.24),version=(int)(width*.145);return new[]{new Rectangle(14,0,name-14,HeaderHeight),new Rectangle(name,0,version,HeaderHeight),new Rectangle(name+version,0,version,HeaderHeight),new Rectangle(name+2*version+16,0,Math.Max(1,width-name-2*version-26),HeaderHeight)};}}
    Rectangle Track{get{return new Rectangle(Width-9,HeaderHeight+5,4,Math.Max(1,Height-HeaderHeight-10));}}
    Rectangle Thumb{get{var r=Track;int h=Math.Min(r.Height,Math.Max(25,r.Height*VisibleRows/Math.Max(1,Items.Length)));return new Rectangle(r.X,r.Y+(r.Height-h)*first/Math.Max(1,Items.Length-VisibleRows),r.Width,h);}}
    void ScrollTo(int row){first=Math.Max(0,Math.Min(Math.Max(0,Items.Length-VisibleRows),row));Invalidate();}
    protected override void OnResize(EventArgs e){base.OnResize(e);ScrollTo(first);var old=Region;if(Width>1&&Height>1)using(var p=UiShape.Round(ClientRectangle,13))Region=new Region(p);if(old!=null)old.Dispose();}
    public void Reload(UpdateItem[] items){string id=Selected==null?null:Selected.Id;items=SectionRows(items);Items=items;SelectedIndex=Array.FindIndex(items,x=>x.Id==id);if(SelectedIndex<0&&items.Length>0)SelectedIndex=Array.FindIndex(items,x=>x.Kind!="section");first=Math.Min(first,Math.Max(0,Items.Length-VisibleRows));Invalidate();if(SelectionChanged!=null)SelectionChanged();}
    static string Version(string value){if(String.IsNullOrEmpty(value))return "—";return value.Length==64?value.Substring(0,8):value.StartsWith("engines-")?value.Substring(7):value;}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;var c=Columns;using(var b=new SolidBrush(Color.FromArgb(25,40,73)))g.FillRectangle(b,0,0,Width,HeaderHeight);string[] headers={"Компонент","Установлено","На GitHub","Состояние"};for(int k=0;k<4;k++)Draw(g,headers[k],c[k],GlassInk.Muted,false,k==1||k==2);
      for(int i=first;i<Math.Min(Items.Length,first+VisibleRows);i++){var row=Items[i];int y=HeaderHeight+(i-first)*RowHeight;if(row.Kind=="section"){Draw(g,row.Name,new Rectangle(16,y+8,Width-40,RowHeight-16),Color.FromArgb(194,83,113),false,false,groupFont);using(var line=new Pen(Color.FromArgb(55,78,109,152)))g.DrawLine(line,16,y+RowHeight-8,Width-24,y+RowHeight-8);continue;}using(var b=new SolidBrush(i==SelectedIndex?Color.FromArgb(45,65,108):i%2==0?Color.FromArgb(29,45,80):BackColor))g.FillRectangle(b,0,y,Width-14,RowHeight);if(i==SelectedIndex)using(var b=new SolidBrush(GlassInk.Cyan))g.FillRectangle(b,0,y+10,3,RowHeight-20);
        Draw(g,row.Name,new Rectangle(c[0].X,y+9,c[0].Width-8,25),GlassInk.White);Draw(g,row.Group,new Rectangle(c[0].X,y+33,c[0].Width-8,21),GlassInk.Muted,false,false,groupFont);
        for(int k=1;k<=2;k++)Draw(g,Version(k==1?row.Current:row.Version),new Rectangle(c[k].X,y+8,c[k].Width,RowHeight-16),k==2&&row.Available&&!row.Ignored?GlassInk.Cyan:GlassInk.Muted,false,true);
        string status=(row.Ignored?"Пропущено · ":"")+row.DisplayStatus;Color ink=row.Ignored?GlassInk.Muted:row.Available?GlassInk.Cyan:row.Status!=null&&row.Status.StartsWith("Не удалось")?Color.FromArgb(255,167,183):row.IsCurrent||row.Status!=null&&row.Status.StartsWith("Обновлено")?GlassInk.Mint:GlassInk.Muted;
        Draw(g,status,new Rectangle(c[3].X,y+7,c[3].Width,RowHeight-14),ink,true);
        using(var p=new Pen(Color.FromArgb(38,56,93)))g.DrawLine(p,14,y+RowHeight-1,Width-20,y+RowHeight-1);
      }
      if(Items.Length>VisibleRows){using(var b=new SolidBrush(Color.FromArgb(51,68,108)))g.FillRectangle(b,Track);using(var b=new SolidBrush(Color.FromArgb(135,157,207)))g.FillRectangle(b,Thumb);}}
    void Draw(Graphics g,string text,Rectangle r,Color color,bool wrap=false,bool center=false,Font font=null){var flags=TextFormatFlags.NoPrefix|TextFormatFlags.PreserveGraphicsClipping|TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|(wrap?TextFormatFlags.WordBreak:TextFormatFlags.SingleLine)|(center?TextFormatFlags.HorizontalCenter:TextFormatFlags.Left);TextRenderer.DrawText(g,text??"",font??Font,r,color,flags);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;Focus();if(Items.Length>VisibleRows&&e.X>=Width-15&&e.Y>=HeaderHeight){var thumb=Thumb;if(thumb.Contains(e.Location)){dragOffset=e.Y-thumb.Y;Capture=true;}else ScrollTo(first+(e.Y<thumb.Y?-VisibleRows:VisibleRows));return;}int index=first+(e.Y-HeaderHeight)/RowHeight;if(e.Y>=HeaderHeight&&index<Items.Length&&index<first+VisibleRows&&Items[index].Kind!="section"){SelectedIndex=index;Invalidate();if(SelectionChanged!=null)SelectionChanged();}}
    protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragOffset>=0){var track=Track;ScrollTo((int)Math.Round((double)(e.Y-dragOffset-track.Y)*Math.Max(0,Items.Length-VisibleRows)/Math.Max(1,track.Height-Thumb.Height)));return;}int index=first+(e.Y-HeaderHeight)/RowHeight;string value=e.Y>=HeaderHeight&&index<Items.Length&&index<first+VisibleRows?Items[index].Name+"\n"+Items[index].Status+"\n"+Items[index].Url:"";if(tips.GetToolTip(this)!=value)tips.SetToolTip(this,value);}
    protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);dragOffset=-1;Capture=false;}
    protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture)dragOffset=-1;}
    protected override void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);if(e.Delta!=0)ScrollTo(first-Math.Sign(e.Delta)*3);}
    protected override bool IsInputKey(Keys key){return key==Keys.Up||key==Keys.Down||key==Keys.PageUp||key==Keys.PageDown||base.IsInputKey(key);}
    protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);int delta=e.KeyCode==Keys.Down?1:e.KeyCode==Keys.Up?-1:e.KeyCode==Keys.PageDown?VisibleRows:e.KeyCode==Keys.PageUp?-VisibleRows:0;if(delta==0||Items.Length==0)return;SelectedIndex=Math.Max(0,Math.Min(Items.Length-1,SelectedIndex+delta));while(SelectedIndex>=0&&SelectedIndex<Items.Length&&Items[SelectedIndex].Kind=="section"){int next=SelectedIndex+Math.Sign(delta);if(next<0||next>=Items.Length)break;SelectedIndex=next;}if(SelectedIndex<first)first=SelectedIndex;if(SelectedIndex>=first+VisibleRows)first=SelectedIndex-VisibleRows+1;Invalidate();if(SelectionChanged!=null)SelectionChanged();e.Handled=true;}
  }
  public sealed partial class MainForm {
