      var check=B("Проверить сейчас",async(s,e)=>await CheckUpdates(false),true);check.Name="updateCheck";check.SetBounds(box.Width-224,61,202,37);check.Anchor=AnchorStyles.Top|AnchorStyles.Right;box.Controls.Add(check);
      var list=new UpdateListView();list.SetBounds(22,110,box.Width-44,Math.Max(108,box.Height-257));list.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;box.Controls.Add(list);
      var detail=L("",10,false,Muted);detail.Name="updateDetail";detail.AutoSize=false;detail.SetBounds(22,box.Height-130,box.Width-44,57);detail.Anchor=AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;box.Controls.Add(detail);
      var progress=new EngineProgress{Name="updateProgress",Location=new Point(22,box.Height-72),Size=new Size(box.Width-44,14),Anchor=AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right};box.Controls.Add(progress);
