      var timer=new Timer{Interval=180};UpdateItem[] shown=null;Action refresh=()=>{if(box.IsDisposed)return;var current=Updates.Items.ToArray();if(shown==null||shown.Length!=current.Length||!shown.SequenceEqual(current)){shown=current;list.Reload(shown);}var row=list.Selected;check.Enabled=!Updates.Checking&&!Updates.Installing;check.Text=Updates.Checking?"Проверяем…":"Проверить сейчас";progress.Visible=Updates.Checking||Updates.Installing;progress.Percent=Updates.Checking?15:row!=null&&row.Kind=="optional"&&Updates.Installing?core.Engines.State(row.Package.Id).Percent:Updates.Progress;progress.Invalidate();detail.Text=Updates.Checking||Updates.Installing?Updates.Activity:row==null?Updates.CheckedAt==DateTime.MinValue?"Нажмите «Проверить сейчас» или дождитесь фоновой проверки.":"Проверено: "+Updates.CheckedAt.ToString("dd.MM.yyyy HH:mm:ss"):row.Name+" · "+row.Status+(row.Kind=="list"?"\nЛокальная копия сохраняется. Изменения применяются при повторном включении модулей.":row.Kind=="text"||row.Kind=="flowseal"||row.Kind=="zapret"?"\nСохранённые стратегии не выбираются заново автоматически; после обновления повторите тесты.":"");apply.Enabled=row!=null&&(row.Available||(row.Kind=="optional"&&!core.Engines.Installed(row.Package.Id)))&&row.Kind!="link"&&row.Kind!="catalog"&&!Updates.Checking&&!Updates.Installing;apply.Text=row!=null&&row.Kind=="app"?(String.IsNullOrEmpty(row.AppliedVersion)?"Скачать обновление":"Установить и перезапустить"):(row!=null&&row.Kind=="optional"&&!core.Engines.Installed(row.Package.Id)?"Скачать движок":"Обновить выбранное");release.Enabled=row!=null&&!String.IsNullOrEmpty(row.Url);skip.Enabled=row!=null&&row.Available&&!Updates.Installing&&!Updates.Checking;list.Invalidate();};list.SelectionChanged+=refresh;timer.Tick+=(s,e)=>refresh();refresh();timer.Start();box.Disposed+=(s,e)=>timer.Dispose();
    }
    void InstallAppUpdate(UpdateItem row){if(core.Running||zapret.Running||telegramBridge.Running||connecting||zapretCancellation!=null||warpCancellation!=null){Toast("Сначала выключите все подключения и проверки");return;}if(!File.Exists(row.AppliedVersion)||AppUpdates.HashFile(row.AppliedVersion)!=row.Asset.digest.Substring(7))throw new InvalidDataException("Скачанное обновление изменилось. Проверьте и скачайте заново");string target=Application.ExecutablePath;if(Path.GetFileName(target).ToLowerInvariant()!="mcrf.exe")throw new InvalidOperationException("Обновление доступно для файла mcrf.exe");string script=AppUpdateInstaller.Script(Process.GetCurrentProcess().Id,row.AppliedVersion,target,row.Asset.digest.Substring(7),store.FilePath);string encoded=Convert.ToBase64String(Encoding.Unicode.GetBytes(script));var psi=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe"),"-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand "+encoded){UseShellExecute=false,CreateNoWindow=true};Process.Start(psi);Close();}
