  public static class AppUpdateInstaller {
    static string Quote(string value){return "'"+value.Replace("'","''")+"'";}
    public static string ReadyEvent;
    public static void ConfirmStartup(){if(!System.Text.RegularExpressions.Regex.IsMatch(ReadyEvent??"", @"^Local\\MCRF-update-[a-f0-9]{32}$"))return;try{using(var signal=System.Threading.EventWaitHandle.OpenExisting(ReadyEvent))signal.Set();}catch(System.Threading.WaitHandleCannotBeOpenedException){}catch(UnauthorizedAccessException){}}
    public static string Script(int pid,string source,string target,string sha,string settingsFile=null){
      if(!System.Text.RegularExpressions.Regex.IsMatch(sha??"", @"^[a-fA-F0-9]{64}$"))throw new InvalidDataException("Некорректный SHA-256");
      return "$ErrorActionPreference='Stop'; $taskSource="+Quote(Path.GetFullPath(source))+"; $taskTarget="+Quote(Path.GetFullPath(target))+"; $taskSettings="+(settingsFile==null?"$null":Quote(Path.GetFullPath(settingsFile)))+"; "+
        "$taskTag=[Guid]::NewGuid().ToString('N'); $taskBackup=$taskTarget+'.previous-'+$taskTag; $taskStage=$taskTarget+'.new-'+$taskTag; $taskSettingsBackup=if($taskSettings){$taskSettings+'.before-update-'+$taskTag}else{$null}; $taskReplaced=$false; $taskNew=$null; $taskEvent=$null; "+
        "try { Wait-Process -Id "+pid+" -Timeout 90 -ErrorAction SilentlyContinue; if(Get-Process -Id "+pid+" -ErrorAction SilentlyContinue){throw 'MCRF is still running'}; "+
        "if((Get-FileHash -LiteralPath $taskSource -Algorithm SHA256).Hash -ne "+Quote(sha)+"){throw 'SHA256 mismatch'}; "+
        "if($taskSettings -and (Test-Path -LiteralPath $taskSettings)){Copy-Item -LiteralPath $taskSettings -Destination $taskSettingsBackup}; "+
        "$taskEventName='Local\\MCRF-update-'+$taskTag; $taskSecurity=[Security.AccessControl.EventWaitHandleSecurity]::new(); $taskSid=[Security.Principal.WindowsIdentity]::GetCurrent().User; $taskRule=[Security.AccessControl.EventWaitHandleAccessRule]::new($taskSid,[Security.AccessControl.EventWaitHandleRights]::FullControl,[Security.AccessControl.AccessControlType]::Allow); $taskSecurity.SetAccessRuleProtection($true,$false); $taskSecurity.AddAccessRule($taskRule); $taskCreated=$false; $taskEvent=[Threading.EventWaitHandle]::new($false,[Threading.EventResetMode]::ManualReset,$taskEventName,[ref]$taskCreated,$taskSecurity); if(-not $taskCreated){throw 'Readiness event collision'}; "+
        "Copy-Item -LiteralPath $taskSource -Destination $taskStage; [IO.File]::Replace($taskStage,$taskTarget,$taskBackup); $taskReplaced=$true; "+
        "$taskNew=Start-Process -FilePath $taskTarget -ArgumentList ('--update-ready-event='+$taskEventName) -WindowStyle Hidden -PassThru; $taskReady=$false; $taskWatch=[Diagnostics.Stopwatch]::StartNew(); "+
        "while($taskWatch.Elapsed.TotalSeconds -lt 90){if($taskEvent.WaitOne(500)){$taskReady=$true;break}; if($taskNew.HasExited){break}}; if(-not $taskReady){throw 'New MCRF failed its startup health check'} "+
        "} catch { $_.Exception.Message | Out-File -LiteralPath ($taskSource+'.install-error.txt'); "+
        "if($taskReplaced){if($taskNew -and -not $taskNew.HasExited){$taskNew.Kill(); $taskNew.WaitForExit()}; [IO.File]::Replace($taskBackup,$taskTarget,$taskTarget+'.failed-'+$taskTag); if($taskSettingsBackup -and (Test-Path -LiteralPath $taskSettingsBackup)){if(Test-Path -LiteralPath $taskSettings){[IO.File]::Replace($taskSettingsBackup,$taskSettings,$taskSettings+'.failed-'+$taskTag)}else{[IO.File]::Move($taskSettingsBackup,$taskSettings)}}}; "+
        "if(-not(Get-Process -Id "+pid+" -ErrorAction SilentlyContinue)){Start-Process -FilePath $taskTarget -WindowStyle Hidden} "+
        "} finally {if($taskEvent){$taskEvent.Dispose()}}";
    }
  }
